package com.kotoba.window;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.PixelFormat;import android.graphics.Color;import android.provider.Settings;import android.view.*;import android.widget.*;
public class OverlayService extends Service {
 WindowManager wm;WindowManager.LayoutParams params;LinearLayout root;StudyView study;boolean collapsed=false;int fullHeight;BroadcastReceiver screen;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){return START_NOT_STICKY;}
 public void onCreate(){super.onCreate();NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("study","悬浮背词",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=new Notification.Builder(this,"study").setSmallIcon(com.kotoba.window.R.drawable.icon).setContentTitle("小词窗悬浮卡片").setContentText("点击返回主界面并关闭悬浮窗").setContentIntent(open).setOngoing(true).build();startForeground(1,n);
 if(!Settings.canDrawOverlays(this)){stopSelf();return;}try{wm=(WindowManager)getSystemService(WINDOW_SERVICE);study=new StudyView(this,true);root=new LinearLayout(this);root.setOrientation(1);LinearLayout bar=new LinearLayout(this);bar.setBackgroundColor(study.quiet()?0x30202535:0xcc202535);TextView handle=new TextView(this);handle.setText("あ 小词窗  ⠿");handle.setTextColor(Color.WHITE);handle.setGravity(Gravity.CENTER);bar.addView(handle,new LinearLayout.LayoutParams(0,study.dp(42),1));Button collapse=study.button("−",()->{},false);bar.addView(collapse,new LinearLayout.LayoutParams(study.dp(48),study.dp(42)));Button close=study.button("×",()->{},false);bar.addView(close,new LinearLayout.LayoutParams(study.dp(48),study.dp(42)));close.setOnClickListener(v->stopSelf());root.addView(bar);root.addView(study,new LinearLayout.LayoutParams(-1,0,1));int width=Math.min(study.dp(330),getResources().getDisplayMetrics().widthPixels-study.dp(24));fullHeight=Math.min(study.dp(570),getResources().getDisplayMetrics().heightPixels-study.dp(120));params=new WindowManager.LayoutParams(width,fullHeight,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.LEFT;params.x=study.dp(12);params.y=study.dp(80);collapse.setOnClickListener(v->{collapsed=!collapsed;study.active=!collapsed;Voice.get(this).stop();study.setVisibility(collapsed?View.GONE:View.VISIBLE);params.height=collapsed?study.dp(42):fullHeight;collapse.setText(collapsed?"+":"−");wm.updateViewLayout(root,params);});handle.setOnTouchListener(new View.OnTouchListener(){int x,y;float rx,ry;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){x=params.x;y=params.y;rx=e.getRawX();ry=e.getRawY();return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){params.x=Math.max(0,Math.min(getResources().getDisplayMetrics().widthPixels-params.width,x+(int)(e.getRawX()-rx)));params.y=Math.max(0,Math.min(getResources().getDisplayMetrics().heightPixels-params.height,y+(int)(e.getRawY()-ry)));wm.updateViewLayout(root,params);return true;}return true;}});wm.addView(root,params);
 screen=new BroadcastReceiver(){public void onReceive(Context c,Intent i){Voice.get(c).stop();}};if(Build.VERSION.SDK_INT>=33)registerReceiver(screen,new IntentFilter(Intent.ACTION_SCREEN_OFF),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(screen,new IntentFilter(Intent.ACTION_SCREEN_OFF));
 }catch(Exception e){Toast.makeText(this,"无法显示悬浮窗："+e.getMessage(),1).show();stopSelf();}}
 public void onDestroy(){Voice.get(this).stop();if(root!=null&&root.isAttachedToWindow())wm.removeView(root);if(screen!=null)unregisterReceiver(screen);stopForeground(true);super.onDestroy();}
}